cd /Users/jyl/work/repo/ai-agent-live/super-planer/pocs/frontend && cat > .shots/vf1d-probe.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch(); const p = await b.newPage({viewport:{width:1586,height:992}});
await p.goto('http://localhost:3200/document'); await p.waitForTimeout(1000);
console.log(await p.evaluate(()=>[...document.querySelectorAll('.overflow-y-auto')].map(e=>[e.scrollHeight,e.clientHeight,e.offsetWidth-e.clientWidth])));
const el = await p.$('.overflow-y-auto'); await el.evaluate(e=>e.scrollTop=e.scrollHeight);
await p.waitForTimeout(300); await p.screenshot({path:'.shots/vf1d-scrolled.png'}); await b.close();
EOF
cp .shots/vf1d-probe.mjs scripts-tmp-probe.mjs 2>/dev/null; node .shots/vf1d-probe.mjs; rm -f scripts-tmp-probe.mjs

